"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9226],{1475:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"0.1.0 (latest)","banner":null,"badge":true,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"documentationSidebar":[{"type":"link","href":"/unique-engine/docs/intro","label":"Getting Started","docId":"intro","unlisted":false},{"type":"link","href":"/unique-engine/docs/core-concepts","label":"Core Concepts","docId":"core-concepts","unlisted":false},{"type":"link","href":"/unique-engine/docs/creating-and-using-meshes","label":"Creating and Using Meshes","docId":"creating-and-using-meshes","unlisted":false},{"type":"link","href":"/unique-engine/docs/materials-and-shaders","label":"Materials & Shaders","docId":"materials-and-shaders","unlisted":false},{"type":"link","href":"/unique-engine/docs/transform-and-matrix-updates","label":"Transform & Matrix Updates","docId":"transform-and-matrix-updates","unlisted":false},{"type":"category","label":"API Reference","collapsible":true,"collapsed":true,"items":[{"type":"category","label":"Core","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/core/UeObject3D","label":"UeObject3D","docId":"reference/core/UeObject3D","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeVertexFormat","label":"UeVertexFormat","docId":"reference/core/UeVertexFormat","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeBufferGeometry","label":"UeBufferGeometry","docId":"reference/core/UeBufferGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeTexture","label":"UeTexture","docId":"reference/core/UeTexture","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeScene","label":"UeScene","docId":"reference/core/UeScene","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeRenderer","label":"UeRenderer","docId":"reference/core/UeRenderer","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeMaterial","label":"UeMaterial","docId":"reference/core/UeMaterial","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeInstanceList","label":"UeInstanceList","docId":"reference/core/UeInstanceList","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeRaycaster","label":"UeRaycaster","docId":"reference/core/UeRaycaster","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeLayers","label":"UeLayers","docId":"reference/core/UeLayers","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/core/UeEventDispatcher","label":"UeEventDispatcher","docId":"reference/core/UeEventDispatcher","unlisted":false}]},{"type":"category","label":"Geometries","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/geometries/UePlaneGeometry","label":"UePlaneGeometry","docId":"reference/geometries/UePlaneGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeBoxGeometry","label":"UeBoxGeometry","docId":"reference/geometries/UeBoxGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeCircleGeometry","label":"UeCircleGeometry","docId":"reference/geometries/UeCircleGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeSphereGeometry","label":"UeSphereGeometry","docId":"reference/geometries/UeSphereGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UePyramidGeometry","label":"UePyramidGeometry","docId":"reference/geometries/UePyramidGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeLineSegmentsGeometry","label":"UeLineSegmentsGeometry","docId":"reference/geometries/UeLineSegmentsGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeLineGeometry","label":"UeLineGeometry","docId":"reference/geometries/UeLineGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeConeGeometry","label":"UeConeGeometry","docId":"reference/geometries/UeConeGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeCylinderGeometry","label":"UeCylinderGeometry","docId":"reference/geometries/UeCylinderGeometry","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/geometries/UeArrowGeometry","label":"UeArrowGeometry","docId":"reference/geometries/UeArrowGeometry","unlisted":false}]},{"type":"category","label":"Objects","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/objects/UeMesh","label":"UeMesh","docId":"reference/objects/UeMesh","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/objects/UeStaticMesh","label":"UeStaticMesh","docId":"reference/objects/UeStaticMesh","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/objects/UeLine","label":"UeLine","docId":"reference/objects/UeLine","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/objects/UeLineSegments","label":"UeLineSegments","docId":"reference/objects/UeLineSegments","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/objects/UeSprite","label":"UeSprite","docId":"reference/objects/UeSprite","unlisted":false}]},{"type":"category","label":"Controls","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/controls/UeControls","label":"UeControls","docId":"reference/controls/UeControls","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/controls/UeOrbitControls","label":"UeOrbitControls","docId":"reference/controls/UeOrbitControls","unlisted":false}]},{"type":"category","label":"Materials","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/materials/UeLineBasicMaterial","label":"UeLineBasicMaterial","docId":"reference/materials/UeLineBasicMaterial","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/materials/UeMeshBasicMaterial","label":"UeMeshBasicMaterial","docId":"reference/materials/UeMeshBasicMaterial","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/materials/UeMeshStandardMaterial","label":"UeMeshStandardMaterial","docId":"reference/materials/UeMeshStandardMaterial","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/materials/UeSpriteMaterial","label":"UeSpriteMaterial","docId":"reference/materials/UeSpriteMaterial","unlisted":false}]},{"type":"category","label":"Cameras","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/cameras/UeCamera","label":"UeCamera","docId":"reference/cameras/UeCamera","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/cameras/UePerspectiveCamera","label":"UePerspectiveCamera","docId":"reference/cameras/UePerspectiveCamera","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/cameras/UeOrthographicCamera","label":"UeOrthographicCamera","docId":"reference/cameras/UeOrthographicCamera","unlisted":false}]},{"type":"category","label":"Lights","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/lights/UeLight","label":"UeLight","docId":"reference/lights/UeLight","unlisted":false},{"type":"category","label":"Shadows","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/lights/shadows/UeLightShadow","label":"UeLightShadow","docId":"reference/lights/shadows/UeLightShadow","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/lights/shadows/UePointLightShadow","label":"UePointLightShadow","docId":"reference/lights/shadows/UePointLightShadow","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/lights/shadows/UeDirectionalLightShadow","label":"UeDirectionalLightShadow","docId":"reference/lights/shadows/UeDirectionalLightShadow","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/lights/shadows/UeShadowMap","label":"UeShadowMap","docId":"reference/lights/shadows/UeShadowMap","unlisted":false}]}]},{"type":"category","label":"Math","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/math/UeTransform","label":"UeTransform","docId":"reference/math/UeTransform","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeVector2","label":"UeVector2","docId":"reference/math/UeVector2","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeVector3","label":"UeVector3","docId":"reference/math/UeVector3","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeMatrix3","label":"UeMatrix3","docId":"reference/math/UeMatrix3","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeMatrix4","label":"UeMatrix4","docId":"reference/math/UeMatrix4","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeQuaternion","label":"UeQuaternion","docId":"reference/math/UeQuaternion","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UePlane","label":"UePlane","docId":"reference/math/UePlane","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeRay","label":"UeRay","docId":"reference/math/UeRay","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeBox2","label":"UeBox2","docId":"reference/math/UeBox2","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeBox3","label":"UeBox3","docId":"reference/math/UeBox3","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeSphere","label":"UeSphere","docId":"reference/math/UeSphere","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeFrustum","label":"UeFrustum","docId":"reference/math/UeFrustum","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/math/UeEuler","label":"UeEuler","docId":"reference/math/UeEuler","unlisted":false}]},{"type":"category","label":"Loaders","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/loaders/UeAssimpLoader","label":"UeAssimpLoader","docId":"reference/loaders/UeAssimpLoader","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/loaders/UeBufferLoader","label":"UeBufferLoader","docId":"reference/loaders/UeBufferLoader","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/loaders/UeMtlLoader","label":"UeMtlLoader","docId":"reference/loaders/UeMtlLoader","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/loaders/UeObjLoader","label":"UeObjLoader","docId":"reference/loaders/UeObjLoader","unlisted":false}]},{"type":"category","label":"Exporters","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/exporters/UeBufferExporter","label":"UeBufferExporter","docId":"reference/exporters/UeBufferExporter","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/exporters/UeBufferLoader","label":"UeBufferLoader","docId":"reference/exporters/UeBufferLoader","unlisted":false}]},{"type":"category","label":"Helpers","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/helpers/UeBoxHelper","label":"UeBoxHelper","docId":"reference/helpers/UeBoxHelper","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/helpers/UeArrowHelper","label":"UeArrowHelper","docId":"reference/helpers/UeArrowHelper","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/helpers/UeAxesHelper","label":"UeAxesHelper","docId":"reference/helpers/UeAxesHelper","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/helpers/UeGridHelper","label":"UeGridHelper","docId":"reference/helpers/UeGridHelper","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/helpers/UeCameraHelper","label":"UeCameraHelper","docId":"reference/helpers/UeCameraHelper","unlisted":false}]},{"type":"category","label":"Utils","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/unique-engine/docs/reference/utils/UeMouse","label":"UeMouse","docId":"reference/utils/UeMouse","unlisted":false},{"type":"link","href":"/unique-engine/docs/reference/utils/UeShadowMapViewer","label":"UeShadowMapViewer","docId":"reference/utils/UeShadowMapViewer","unlisted":false}]}]}],"changelogSidebar":[]},"docs":{"core-concepts":{"id":"core-concepts","title":"Core Concepts","description":"Unique Engine is built around a clear and modular architecture. Before diving deeper, it\'s important to understand the main building blocks of the engine.","sidebar":"documentationSidebar"},"creating-and-using-meshes":{"id":"creating-and-using-meshes","title":"Creating and Using Meshes","description":"Meshes are built from geometry classes (primitives), which define their vertex data. Each geometry can be reused across multiple meshes, and passed directly when creating a new mesh.","sidebar":"documentationSidebar"},"intro":{"id":"intro","title":"Getting Started","description":"Welcome to Unique Engine, a modular 3D engine built for GameMaker and inspired by the power and design of Three.js.","sidebar":"documentationSidebar"},"materials-and-shaders":{"id":"materials-and-shaders","title":"Materials & Shaders","description":"Materials define how your 3D objects look \u2014 their color, texture, lighting, and more. In Unique Engine, materials are tightly integrated with the rendering pipeline and automatically pass data to the appropriate shaders.","sidebar":"documentationSidebar"},"reference/cameras/UeCamera":{"id":"reference/cameras/UeCamera","title":"UeCamera","description":"The UeCamera is an abstract base class for all cameras in Unique Engine.","sidebar":"documentationSidebar"},"reference/cameras/UeOrthographicCamera":{"id":"reference/cameras/UeOrthographicCamera","title":"UeOrthographicCamera","description":"The UeOrthographicCamera class creates a 3D camera with orthographic projection in Unique Engine.","sidebar":"documentationSidebar"},"reference/cameras/UePerspectiveCamera":{"id":"reference/cameras/UePerspectiveCamera","title":"UePerspectiveCamera","description":"The UePerspectiveCamera class creates a 3D camera with a perspective projection in Unique Engine.","sidebar":"documentationSidebar"},"reference/controls/UeControls":{"id":"reference/controls/UeControls","title":"UeControls","description":"Base class extended from other Controls classes","sidebar":"documentationSidebar"},"reference/controls/UeOrbitControls":{"id":"reference/controls/UeOrbitControls","title":"UeOrbitControls","description":"The UeOrbitControls class allows orbit-style camera manipulation around a target point.","sidebar":"documentationSidebar"},"reference/core/UeBufferGeometry":{"id":"reference/core/UeBufferGeometry","title":"UeBufferGeometry","description":"A geometry class representing a buffer geometry, optimized for GPU rendering.","sidebar":"documentationSidebar"},"reference/core/UeEventDispatcher":{"id":"reference/core/UeEventDispatcher","title":"UeEventDispatcher","description":"Base class that provides a lightweight event system for all engine objects. It is used as the parent class for UeTransform, which means every object that inherits from UeTransform (including UeObject3D, UeMesh, cameras, etc.) automatically gains event capabilities.","sidebar":"documentationSidebar"},"reference/core/UeInstanceList":{"id":"reference/core/UeInstanceList","title":"UeInstanceList","description":"A helper class to manage instances of a UeObject3D. It allows for efficient rendering and management of multiple objects that share the same geometry and material.","sidebar":"documentationSidebar"},"reference/core/UeLayers":{"id":"reference/core/UeLayers","title":"UeLayers","description":"The UeLayers class manages membership of an object in up to 32 layers (0 to 31), represented internally as a bitmask. By default, an object is assigned to layer 0.","sidebar":"documentationSidebar"},"reference/core/UeMaterial":{"id":"reference/core/UeMaterial","title":"UeMaterial","description":"The UeMaterial class defines the visual appearance of a UeMesh, including color, transparency, shading, blending, lighting, and custom shader uniforms and textures.","sidebar":"documentationSidebar"},"reference/core/UeObject3D":{"id":"reference/core/UeObject3D","title":"UeObject3D","description":"The base class for all 3D entities in Unique Engine. Inherits from UeTransform, and acts as a hierarchical scene graph node.","sidebar":"documentationSidebar"},"reference/core/UeRaycaster":{"id":"reference/core/UeRaycaster","title":"UeRaycaster","description":"A raycaster utility for performing ray-object intersection tests in 3D space.","sidebar":"documentationSidebar"},"reference/core/UeRenderer":{"id":"reference/core/UeRenderer","title":"UeRenderer","description":"UeRenderer is responsible for rendering the scene, collecting visible objects, computing their sort order using a 52-bit packed integer key, building the lighting state, and issuing the draw calls.","sidebar":"documentationSidebar"},"reference/core/UeScene":{"id":"reference/core/UeScene","title":"UeScene","description":"The UeScene class represents the root node of a 3D scene in Unique Engine. It inherits from UeObject3D and adds logic for managing lights and renderable objects.","sidebar":"documentationSidebar"},"reference/core/UeTexture":{"id":"reference/core/UeTexture","title":"UeTexture","description":"A texture wrapper class for GameMaker that supports UV transformations, wrapping modes, tiling, flipping, rotation, filtering, and mipmap generation. Transforms are baked into a surface and converted into a GPU-ready sprite.","sidebar":"documentationSidebar"},"reference/core/UeVertexFormat":{"id":"reference/core/UeVertexFormat","title":"UeVertexFormat","description":"The UeVertexFormat class defines the layout of vertex data for a UeBufferGeometry. It acts as a chainable builder for setting attributes like position, normal, UV, color, and custom fields.","sidebar":"documentationSidebar"},"reference/exporters/UeBufferExporter":{"id":"reference/exporters/UeBufferExporter","title":"UeBufferExporter","description":"The UeBufferExporter class provides functionality to serialize scenes or meshes into binary buffers for storage or network transmission.","sidebar":"documentationSidebar"},"reference/exporters/UeBufferLoader":{"id":"reference/exporters/UeBufferLoader","title":"UeBufferLoader","description":"","sidebar":"documentationSidebar"},"reference/geometries/UeArrowGeometry":{"id":"reference/geometries/UeArrowGeometry","title":"UeArrowGeometry","description":"Inherits from UeBufferGeometry","sidebar":"documentationSidebar"},"reference/geometries/UeBoxGeometry":{"id":"reference/geometries/UeBoxGeometry","title":"UeBoxGeometry","description":"Can be used also for parallelepipeds","sidebar":"documentationSidebar"},"reference/geometries/UeCircleGeometry":{"id":"reference/geometries/UeCircleGeometry","title":"UeCircleGeometry","description":"Inherits from UeBufferGeometry","sidebar":"documentationSidebar"},"reference/geometries/UeConeGeometry":{"id":"reference/geometries/UeConeGeometry","title":"UeConeGeometry","description":"Represents a 3D cone geometry aligned along the negative Z axis (\u2212Z), suitable for use in directional helpers like arrows or rays.","sidebar":"documentationSidebar"},"reference/geometries/UeCylinderGeometry":{"id":"reference/geometries/UeCylinderGeometry","title":"UeCylinderGeometry","description":"Inherits from UeBufferGeometry","sidebar":"documentationSidebar"},"reference/geometries/UeLineGeometry":{"id":"reference/geometries/UeLineGeometry","title":"UeLineGeometry","description":"A chain of vertices connected together, forming a polyline.","sidebar":"documentationSidebar"},"reference/geometries/UeLineSegmentsGeometry":{"id":"reference/geometries/UeLineSegmentsGeometry","title":"UeLineSegmentsGeometry","description":"Represents a series of individual line segments, each defined by a pair of 3D points. This class is useful for drawing disconnected line pairs, such as wireframes or outlines.","sidebar":"documentationSidebar"},"reference/geometries/UePlaneGeometry":{"id":"reference/geometries/UePlaneGeometry","title":"UePlaneGeometry","description":"Inherits from UeBufferGeometry","sidebar":"documentationSidebar"},"reference/geometries/UePyramidGeometry":{"id":"reference/geometries/UePyramidGeometry","title":"UePyramidGeometry","description":"Inherits from UeBufferGeometry","sidebar":"documentationSidebar"},"reference/geometries/UeSphereGeometry":{"id":"reference/geometries/UeSphereGeometry","title":"UeSphereGeometry","description":"Inherits from UeBufferGeometry","sidebar":"documentationSidebar"},"reference/helpers/UeArrowHelper":{"id":"reference/helpers/UeArrowHelper","title":"UeArrowHelper","description":"Visual helper that represents a 3D arrow using a shaft (line) and a head (cone).","sidebar":"documentationSidebar"},"reference/helpers/UeAxesHelper":{"id":"reference/helpers/UeAxesHelper","title":"UeAxesHelper","description":"Displays the 3 main coordinate axes in red (X), green (Y), and blue (Z). Useful for debugging object orientation in 3D space.","sidebar":"documentationSidebar"},"reference/helpers/UeBoxHelper":{"id":"reference/helpers/UeBoxHelper","title":"UeBoxHelper","description":"A helper class that creates and updates a wireframe bounding box around a 3D object.","sidebar":"documentationSidebar"},"reference/helpers/UeCameraHelper":{"id":"reference/helpers/UeCameraHelper","title":"UeCameraHelper","description":"A helper class for visualizing a 3D camera\'s view frustum in world space. Useful for debugging projection matrices, visibility, and frustum culling logic.","sidebar":"documentationSidebar"},"reference/helpers/UeGridHelper":{"id":"reference/helpers/UeGridHelper","title":"UeGridHelper","description":"Visual representation of a two-dimensional grid, useful for positioning and spatial orientation.","sidebar":"documentationSidebar"},"reference/lights/shadows/UeDirectionalLightShadow":{"id":"reference/lights/shadows/UeDirectionalLightShadow","title":"UeDirectionalLightShadow","description":"UeDirectionalLightShadow manages shadow configuration for directional lights. It uses an orthographic camera to capture shadow depth information, simulating sunlight or other distant light sources that produce parallel light rays.","sidebar":"documentationSidebar"},"reference/lights/shadows/UeLightShadow":{"id":"reference/lights/shadows/UeLightShadow","title":"UeLightShadow","description":"UeLightShadow is the base class for light shadow controllers in Unique Engine. It provides common properties and helper methods shared by directional and point light shadows.","sidebar":"documentationSidebar"},"reference/lights/shadows/UePointLightShadow":{"id":"reference/lights/shadows/UePointLightShadow","title":"UePointLightShadow","description":"UePointLightShadow manages shadows for UePointLight using a cube shadow map approach (6 faces). This implementation enables point lights to cast shadows in all directions.","sidebar":"documentationSidebar"},"reference/lights/shadows/UeShadowMap":{"id":"reference/lights/shadows/UeShadowMap","title":"UeShadowMap","description":"UeShadowMap is an internal container for shadow depth information. It manages the render target (surface) used to store shadow depth values during the shadow mapping process.","sidebar":"documentationSidebar"},"reference/lights/UeLight":{"id":"reference/lights/UeLight","title":"UeLight","description":"All lights in Unique Engine inherit from UeLight. These include AmbientLight, DirectionalLight, and PointLight.","sidebar":"documentationSidebar"},"reference/loaders/UeAssimpLoader":{"id":"reference/loaders/UeAssimpLoader","title":"UeAssimpLoader","description":"Import a 3D model and its materials by using an integrated Assimp extension, which supports a variety of 3D formats (obj,3ds,etc..).","sidebar":"documentationSidebar"},"reference/loaders/UeBufferLoader":{"id":"reference/loaders/UeBufferLoader","title":"UeBufferLoader","description":"The UeBufferLoader class provides functionality to deserialize scenes or meshes from binary buffers created by UeBufferExporter.","sidebar":"documentationSidebar"},"reference/loaders/UeMtlLoader":{"id":"reference/loaders/UeMtlLoader","title":"UeMtlLoader","description":"A .mtl material file loader, designed to work with UeObjLoader.","sidebar":"documentationSidebar"},"reference/loaders/UeObjLoader":{"id":"reference/loaders/UeObjLoader","title":"UeObjLoader","description":"A .obj model loader. Supports vertex positions, normals, UVs, vertex colors, material groups, usemtl references, and .mtl material libraries.","sidebar":"documentationSidebar"},"reference/materials/UeLineBasicMaterial":{"id":"reference/materials/UeLineBasicMaterial","title":"UeLineBasicMaterial","description":"A material used for rendering lines with a flat color, without lighting calculations.","sidebar":"documentationSidebar"},"reference/materials/UeMeshBasicMaterial":{"id":"reference/materials/UeMeshBasicMaterial","title":"UeMeshBasicMaterial","description":"A material with a flat color and a simple diffuse texture, that does not receive lights data.","sidebar":"documentationSidebar"},"reference/materials/UeMeshStandardMaterial":{"id":"reference/materials/UeMeshStandardMaterial","title":"UeMeshStandardMaterial","description":"A ready-to-use material with built-in lighting support (ambient, point, directional) and texture handling.","sidebar":"documentationSidebar"},"reference/materials/UeSpriteMaterial":{"id":"reference/materials/UeSpriteMaterial","title":"UeSpriteMaterial","description":"A simplified material for 2D-like rendering of flat meshes or billboards. It uses the shader shuesprite under the hood and does not support lighting.","sidebar":"documentationSidebar"},"reference/math/UeBox2":{"id":"reference/math/UeBox2","title":"UeBox2","description":"A 2D axis-aligned bounding box (AABB) class that defines a rectangle using minimum and maximum Vector2 corners. Useful for spatial partitioning, collision checks, and geometric operations in 2D space.","sidebar":"documentationSidebar"},"reference/math/UeBox3":{"id":"reference/math/UeBox3","title":"UeBox3","description":"A 3D axis-aligned bounding box (AABB) class that defines a cuboid using minimum and maximum Vector3 corners. Useful for spatial partitioning, collision detection, and geometric operations in 3D space.","sidebar":"documentationSidebar"},"reference/math/UeEuler":{"id":"reference/math/UeEuler","title":"UeEuler","description":"Represents Euler angles for rotations in 3D space.","sidebar":"documentationSidebar"},"reference/math/UeFrustum":{"id":"reference/math/UeFrustum","title":"UeFrustum","description":"A class representing a 3D view frustum used for visibility testing and culling operations. It maintains six clipping planes and provides methods to test intersection against points, boxes, spheres, and objects.","sidebar":"documentationSidebar"},"reference/math/UeMatrix3":{"id":"reference/math/UeMatrix3","title":"UeMatrix3","description":"Represents a 3\xd73 matrix, mainly used for 2D/3D transformations like normal matrix calculations, scaling, or other matrix math in compact form.","sidebar":"documentationSidebar"},"reference/math/UeMatrix4":{"id":"reference/math/UeMatrix4","title":"UeMatrix4","description":"A 4x4 matrix class used for 3D transformations such as translation, rotation, scaling, and projection. Operates in column-major order, compatible with GameMaker\'s internal matrix format.","sidebar":"documentationSidebar"},"reference/math/UePlane":{"id":"reference/math/UePlane","title":"UePlane","description":"Represents a mathematical plane in 3D space defined by a normal vector and a distance from the origin. Useful for geometric tests, projections, culling, and physics.","sidebar":"documentationSidebar"},"reference/math/UeQuaternion":{"id":"reference/math/UeQuaternion","title":"UeQuaternion","description":"Represents a quaternion used to encode 3D rotations in a compact and stable way. Useful for interpolating rotations and avoiding gimbal lock, especially in 3D animation and camera movement.","sidebar":"documentationSidebar"},"reference/math/UeRay":{"id":"reference/math/UeRay","title":"UeRay","description":"Represents a ray in 3D space defined by an origin and a normalized direction vector. Commonly used for intersection tests, picking, and visibility checks.","sidebar":"documentationSidebar"},"reference/math/UeSphere":{"id":"reference/math/UeSphere","title":"UeSphere","description":"A bounding sphere defined by a center point and a radius. Useful for spatial queries, collision detection, and bounding volume hierarchies in 3D.","sidebar":"documentationSidebar"},"reference/math/UeTransform":{"id":"reference/math/UeTransform","title":"UeTransform","description":"A UeTransform represents an object\'s position, rotation, and scale in 3D space. It handles local and world transformation matrices, and offers methods to manipulate transforms programmatically.","sidebar":"documentationSidebar"},"reference/math/UeVector2":{"id":"reference/math/UeVector2","title":"UeVector2","description":"A 2D vector class with common vector operations. Useful for positions, directions, and geometry in 2D space.","sidebar":"documentationSidebar"},"reference/math/UeVector3":{"id":"reference/math/UeVector3","title":"UeVector3","description":"A 3D vector class that supports common vector math operations. Used for positions, directions, and geometric calculations in 3D space.","sidebar":"documentationSidebar"},"reference/objects/UeLine":{"id":"reference/objects/UeLine","title":"UeLine","description":"A simple line mesh class that renders a continuous line strip using provided geometry and material.","sidebar":"documentationSidebar"},"reference/objects/UeLineSegments":{"id":"reference/objects/UeLineSegments","title":"UeLineSegments","description":"A line segments mesh class that renders individual line segments between pairs of vertices using provided geometry and material.","sidebar":"documentationSidebar"},"reference/objects/UeMesh":{"id":"reference/objects/UeMesh","title":"UeMesh","description":"The UeMesh class is a renderable object in Unique Engine. It combines a geometry (vertex buffer) with a material and is placed in the scene graph via its transformation.","sidebar":"documentationSidebar"},"reference/objects/UeSprite":{"id":"reference/objects/UeSprite","title":"UeSprite","description":"A UeSprite is a lightweight 2D object rendered as a billboard that always faces the camera.","sidebar":"documentationSidebar"},"reference/objects/UeStaticMesh":{"id":"reference/objects/UeStaticMesh","title":"UeStaticMesh","description":"This is just a wrapper class around UeMesh() which simply sets the matrixAutoUpdate property to false","sidebar":"documentationSidebar"},"reference/utils/UeMouse":{"id":"reference/utils/UeMouse","title":"UeMouse","description":"A global (UE_MOUSE) utility class for retrieving mouse coordinates in game-space and Normalized Device Coordinates (NDC).","sidebar":"documentationSidebar"},"reference/utils/UeShadowMapViewer":{"id":"reference/utils/UeShadowMapViewer","title":"UeShadowMapViewer","description":"UeShadowMapViewer is a debug utility that renders a visual representation of a light\'s shadow map on the screen. This is useful for debugging shadow mapping issues, verifying shadow quality, and understanding how shadows are being rendered.","sidebar":"documentationSidebar"},"transform-and-matrix-updates":{"id":"transform-and-matrix-updates","title":"Transform & Matrix Updates","description":"Every UeObject3D in Unique Engine has its own local UeTransform, and these combine recursively to form the final world transform. The engine handles matrix updates in an efficient way, recalculating them only one time per frame.","sidebar":"documentationSidebar"}}}}')}}]);